def solve(path):
    """Simplify an absolute Unix path: resolve . and .., collapse repeated
    slashes, remove trailing slashes. Root stays '/'. Empty input -> '/'.
    """
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack)

