def solve(n, edges):
    """Return the lexicographically smallest topological order of n nodes, or [] on a cycle."""
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b in edges:
        adj[a].append(b)
        indeg[b] += 1
    heap = [v for v in range(n) if indeg[v] == 0]
    heapq.heapify(heap)
